INSERT INTO `reports` (`id`, `title`, `category`, `content`, `date`, `author`, `published`, `created_at`, `updated_at`) VALUES (1,'Wasserschaden KAT-Lager','einsatz','Am Sonntag, den 11.01.2026, um 13:03 Uhr wurden wir zu einem Wasserschaden im KAT-Lager der Feuerwehr Innsbruck alarmiert. Im Bereich eines Wasserzählers kam es zu einer Leckage, und das Lager des BFV Innsbruck-Stadt sowie die danebenliegenden Räume wurden ca. 5 cm hoch unter Wasser gesetzt. Mittels zwei Wassersaugern wurde der Wasserschaden beseitigt und das Lager des BFV ausgeräumt. Nach knapp einer Stunde konnten wir wieder zusammenräumen und in die Wache einrücken.','2026-01-11','FF Reichenau',1,'2026-04-09 11:31:48','2026-04-09 11:31:48'),(2,'Brand Mehrfamilienhaus - Rauchentwicklung am Dach','einsatz','Das neue Jahr startete genau um Punkt 00:00 Uhr für die FF Reichenau, mit der ersten Alarmierung. Die Alarmmeldung lautete: Radetzkystraße 42, Rauchentwicklung Mehrfamilienhaus am Dach, näheres unbekannt. Die sich auf Bereitschaft befindliche Mannschaft rückte umgehend aus und konnte als Quelle für die Rauchentwicklung die Heizungsanlage des Hauses feststellen.\r\n\nKurz nach dem Einrücken, wurden wir zu einem Brandmeldalarm alarmiert, welcher sich als Fehlalarm herausstellte.\r\n\nNoch an der Einsatzstelle, erhielten wir den nächsten Einsatz und zwar den Brand einer Feuerwerksbatterie im Gutshofpark. Das Kommando arbeitete den BMA noch fertig ab, während die TLF Besatzung sich zum Einsatzort begab. Auf dem Weg dorthin wurde eine regungslose Person am Gehsteig liegend festgestellt. Die Erstversorgung und Betreuung übernahm die Besatzung des Gefahrgutfahrzeuges und das Kommando, während die TLF Besatzung weiter zum Brand anfuhr.\r\n\nNach dem Einrücken wurden wir vom Bereitschaftsoffizier der BF Innsbruck noch zur Bereitschaft auf der Wache angefordert. Die Bereitschaft konnte ohne weiteren Einsatz um 02:00 Uhr beendet werden. \r\n\nWir wünschen allen Bewohner der Stadt Innsbruck ein gutes neues Jahr und vor allem viel Gesundheit.\r\n\n\"UNSERE FREIZEIT FÜR IHRE SICHERHEIT\"\r\n\nHelmut PLANK, Kommandant','2026-01-01','FF Reichenau',1,'2026-04-09 11:31:48','2026-04-09 11:31:48'),(3,'Brand Wald - Nachalarmierung','einsatz','Am Sonntag kurz vor 12:00 Uhr Mittag wurden auch wir zum Waldbrand östlich der Höttinger Alm alarmiert. Es galt Kameraden der FF Zirl und FF Hungerburg am Planötzenhof zur Besetzung des Wasserbehälters, woraus die Hubschrauber das Wasser entnehmen, zu besetzen. Gegen 16:30 Uhr konnten die 5 Kameraden wieder in die Wache einrücken. \r\n\n \r\n\nBereits den 2. Tag waren 2 Kameraden von unserer Einheit zur Besetzung des Feuerwehreinsatzleitfahrzeuges am Gramartboden bzw. Planötzenhof im Einsatz. Am Montag werden wieder 2 Kameraden unserer Einheit das Feuerwehreinsatzleitfahrzeug gemeinsam mit Kameraden anderer FF Einheiten und der BF Innsbruck besetzen. \r\n\n \r\n\nHelmut PLANK, Kommandant','2025-12-28','FF Reichenau',1,'2026-04-09 11:31:48','2026-04-09 11:31:48'),(4,'Brand MFH Wohnung, Hochhaus','einsatz','Am 23.06.2025 kurz nach 21:00 Uhr wurden wir zur Unterstützung der Berufsfeuerwehr zu einem gemeldeten Wohnungsbrand im 11. Stock eines Hochhauses in der Andechsstraße alarmiert. Da wir gerade von einer Gemeinschaftsübung mit der FF Mühlau am Weg in die Wache waren, fuhren wir umgehend mit 4 Fahrzeugen zu der Einsatzörtlichkeit. Dort eingetroffen stellten wir einen Atemschutzreservetrupp. Der Brand konnte durch die BF rasch gelöscht werden. Ein abmontierter Küchenschrank wurde von uns im Freien noch nachgelöscht und wir konnten nach ca. 45 Minuten wieder abrücken. An der Küche entsand großer Sachschaden. Nach dem Einrücken wurden noch die Gerätschaften aufgerüstet und das Übungsmaterial verstaut. \r\n\nHelmut PLANK, Kommandant','2025-06-23','FF Reichenau',1,'2026-04-09 11:31:48','2026-04-09 11:31:48'),(5,'Gemeinschaftsübung mit der FF Mühlau','uebung','Am 23.06.2025 wurden wir von der FF Mühlau zu einer Gemeinschaftsübung, mit den Thema Gefahrgutunfall eingeladen. Einmal war im Freien, beim Verladen eines LKW ein Fass mit \"Essigsäure\" umgestürzt und im Keller der Anlage, war ebenfalls ein Fass mit dem selben Inhalt umgekippt. Die FF Mühlau übernahm in beiden Fällen die Chrashbergung von Personen unter schwerem Atemschutz. Eine Atemschutztrupp unserer Einheit rüstete sich mit Schutzstufe 3 Anzügen (Chemilakenschutzanzügen) aus, während die weiteren Kameraden/Innen gemeinsam mit Kameraden/Innen der FF Mühlau die Dekontaminationsstraße aufbauten. Der SIII Trupp begab sich in den Keller, stellte das Fass auf und verdünnte mit viel Wasser die ausgeflossenen Flüssigkeit. Im Freien wurde das Verdünnen der ausgeflossenen Essigsäure von Kameraden/Innen der FF Mühlau übernommen. Am Schluss der Übung konnten wir die Kameraden/Innen der FF Mühlau noch in die Arbeitsweise bei der Dekostraße informieren bzw. schulen. Zu diesem Zwecke haben wir auch alle Anzüge, welche wir im GGF mitführen, an diesem Abend in Verwendung (S3, S2 und Einweganzüge). Wir bedanken uns recht herzlich für die Einladung und die anschließende Jause vor Ort. \r\n\nNach der Jause ging es für unsere Kameraden/Innen weiter zu einem Realeinsatz, Brand im Hochhaus. Näheres im Einsatzbericht. \r\n\nHelmut PLANK, Kommandant','2025-06-23','FF Reichenau',1,'2026-04-09 11:31:48','2026-04-09 11:31:48'),(6,'THL Sicherungsarbeiten','einsatz','Am Sonntag den 09.03.2025 kurz nach 16:00 Uhr wurden wir auf Grund des Windes zu einem umgestürzten Bauzaun in die Pradler Straße alarmiert. LAST1 und TLFH rückten umgehend aus und stellten den Bauzaun wieder auf. Teils gebrochene Zaunelemente mussten ausgetauscht und der Zaun von der Rückseite her gesichert werden. Der Fußgängerweg in diesem Baustellenbereich wurde abgesperrt. Das restliche Material wurde gesichert in der Absperrung abgelegt. Für die Fußgänger war entlang der Hausmauer noch eine Durchgangsmöglichkeit vorhanden. Während des Einsatzes war das KLF und TF voll besetzt auf Bereitschaft in der Wache.\r\n\nHelmut PLANK, Kommandant','2025-03-09','FF Reichenau',1,'2026-04-09 11:31:48','2026-04-09 11:31:48'),(7,'41. Jahreshauptversammlung','sonstige','41. Jahreshauptversammlung am 07.03.2025\r\n\nZur diesjährigen 41. Jahreshauptversammlung konnten wieder einige Ehrengäste begrüßt werden. Unter anderem\r\n\nv  Pfarrer und Feuerwehrkurat Paul KNEUSSL\r\n\nv  Herr Bürgermeister Ing. Mag. Johannes ANZENGRUBER\r\n\nv  Ing. Marcus WIMMER von der Berufsfeuerwehr Innsbruck\r\n\nv  das gesamte Bezirkskommando unter BFK OBR Gerhard MAYREGGER\r\n\nv  BFK a. D. OBR Albert PFEIFHOFER\r\n\nv  Ehrenmitglied und Ehrenkommandant HBI Armin PRAXMARER\r\n\nNach dem Kassabericht, dem Bericht der Jugend und der Ansprache des Kommandanten kam es zu einer Angelobung, Beförderungen und Auszeichnungen:\r\n\nv  Angelobt und zum Feuerwehrmann/frau befördert wurde FM Irmgard BRANDLHUBER\r\n\nv  Ernannt zum Probefeuerwehrmann wurden Andreas BINDER und Linhard BOYAKE\r\n\nv  Zum Hauptfeuerwehrmann wurde Patrick HEINRICH befördert\r\n\nv  Zum Hauptlöschmeister wurde Mike PELZL befördert\r\n\n    Ausgezeichnet wurden:\r\n\nv  Franz STURM für 30 Jahre Feuerwehrdienst\r\n\nv  Kurt PLANKENSTEINER für 40 Jahre Feuerwehrdienst\r\n\nv  Martin WINDBICHLER für 40 Jahre Feuerwehrdienst\r\n\nAlle anwesenden Ehrengäste bedankten sich für die erbrachten Stunden und Leistungen im abgelaufenen Jahr. Ing. WIMMER zeigte anhand eines Rechenbeispiels sogar auf, dass wir im letzten Jahr fast 140 Stunden pro Woche ehrenamtlich und für das Wohl der Bevölkerung im Dienst waren. Vom Bürgermeister wurde auch nochmals ausgeführt, dass im 6 Jahresprogramm der Stadtregierung verankert ist, dass in dieser Periode über einen Neubau der Feuerwehr Reichenau zumindest geredet und erste Planungsschritte erfolgen sollen. \r\n\nIm abgelaufenen Jahr wurden wir zu 5 Brandeinsätzen, 4 Gefahrguteinsätzen und 34 technischen Einsätze alarmiert. Hervorzuheben sind hier eine gemeldete Explosion in einer Tiefgarage, welche sich dann als PKW Brand herausstellte, die 4 Gefahrguteinsätze und der Unwetterabend am 19.07.2024, wo es Teile der Reichenau schwer erwischt hat und wir bis in die Nacht hinein mit allen Fahrzeugen und dem gesamten Wasserschadenequipment im Dienst standen. Insgesamt leisteten die Kameraden/Innen im abgelaufenen Jahr über 7200 Stunden. Auch Eigenanschaffung von Gerätschaften und Umbaumaßnahmen in der Wache im Wert von fast € 7.000.—wurden in der Ansprache vom Kommandanten dargelegt. Bedanken möchten wir uns hier auch nochmal bei unseren Gönnern der Feuerwehr Reichenau, Markus PILSER vom Autohaus PILSER, Gerhard FARBMACHER von FARBMACHER-KAFFEE und Lars GUNDOLF, dem ehemaligen Geschäftsführer vom Gasthof SANDWIRT AM INN, welcher bereits abgerissen wurde.\r\n\nBedanken möchten wir uns auch noch bei der Schützenkompanie Reichenau für die Zurverfügungstellung des Vereinsheimes und bei Traudi, Sabine und Kurt für die Bewirtung. \r\n\nAuch heuer werden die Kameraden und Kameradinnen der FF Reichenau wieder ehrenamtlich für die Bevölkerung des Schutzgebietes aber auch für die Bevölkerung der gesamten Landeshauptstadt Innsbruck da sein. \r\n\n„GOTT ZUR EHR, DEM NÄCHSTEN ZUR WEHR“','2025-03-07','FF Reichenau',1,'2026-04-09 11:31:48','2026-04-09 11:31:48'),(8,'THL Ölspur','einsatz','Am 13.04.2022 kurz nach 19:00 Uhr wurden wir zur Unterstützung des 1. Trupp der BF Innsbruck zu einer längeren Treibstoffspur alarmiert. Die Treibstoffspur erstreckte sich von der Pradler Straße über die Reichenauer Straße / Andechsstraße / Gumppstraße bis in die Valiergasse. Von unserer Mannschaft welche mit LAST1, TLFH und GGF ausrückte wurde Bindemittel auftragen, eingekehrt und von der Kehrmaschine der Stadt Innsbruck die Abschlussreinigung der Fahrbahn vorgenommen. Um 20:00 Uhr konnte der Einsatz beendet werden. \r\n\nHelmut PLANK, Kommandant','2022-04-13','FF Reichenau',1,'2026-04-09 11:31:48','2026-04-09 11:31:48'),(9,'3 technische Einsätze - Ölspuren','einsatz','Am 20.06.2024 um 11:40 Uhr wurden wir zur Unterstützung der BF Innsbruck zu einer Ölspur quer durch Innsbruck alarmiert. Beginnend von der Pauluskirche erstreckte sich die Ölspur in unserem Schutzgebiet schlussendlich von der Radetzkystraße - Reichenauer Straße - Pembauer Straße - Biener Straße bis zum Bahnviadukt in beiden Fahrtrichtungen. Über 300 kg Bindemittel musste von uns auftragen und eingekehrt werden. Die durch die BF bereits verständigte verständigte Kehrmaschine wurde das Bindemittel dann wieder eingekehrt. \r\n\nDer 2. Einsatz erreichte uns während des noch laufenden ersten Einsatzes in der Andechsstraße, wo bei einem reisebus die Leitung der Servolenkung eine Leck hatte. Hier wurde am Abstellplatz Bindemittel aufgebracht, damit dieser dort, bis zum Eintreffen des Servicedienstes problemlos abgestellt werden konnte. \r\n\nWährend des Auffüllens der leere Bindemittelcontainer in der BF Innsbruck, wurden wir zum 3. Einsatz, wiederum eine Ölspur, in die Franz-Fischer-Straße alarmiert. Dort war bei einem Klein-LKW das gesamte Öl der Ölwanne ausgeflossen. Die Spur reichte von der Leopoldstraße über die Michael-Gaismair-Straße, weiter in die Templstraße und Franz-Fischer-Straße. Auch wurde Bindemittel aufgetragen und eingekehrt. \r\n\nNach Beendigung aller Einsätze, wurde noch die Einsatzbereitschaft hergestellt und die Kameraden/Innen konnten nach ca. 4 Stunden wieder zu ihren Arbeitsstellen bzw. nach Hause fahren. \r\n\nIm Einsatz standen neben der Berufsfeuerwehr Innsbruck und uns, auch noch die Freiwilligen Feuerwehren Amras und Mühlau. \r\n\nHelmut PLANK, Kommandant','2024-06-20','FF Reichenau',1,'2026-04-09 11:31:48','2026-04-09 11:31:48'),(10,'Gefahrguteinsatz','einsatz','Heute um 14:54 Uhr wurden wir gemeinsam mit der Berufsfeuerwehr Innsbruck zu einem Gefahrguteinsatz in einem Gastronomiebetrieb alarmiert. Ein 240 Liter großer CO2 Tank im Keller eines Gebäudes wurde beschädigt, wodurch das CO2 ausgetreten war. Während die Kameraden der BF die Leckage behelfsmäßig abdichteten und das CO2 kontrolliert ins Freie leiteten, bestand unsere Aufgabe darin, den Einsatzort abzusperren und die BF beim Aufbau des Absaug- und Belüftungsgerätes zu unterstützen. Nach etwas über 2 Stunden war der Einsatz für uns beendet und wir rückten wieder ein. Danke an die EL und die gesamte Mannschaft der BF für die gute Zusammenarbeit an der Einsatzstelle. \r\n\nHelmut PLANK, Kommandant','2022-04-17','FF Reichenau',1,'2026-04-09 11:31:48','2026-04-09 11:31:48'),(11,'Brand in Tiefgarage','einsatz','Am 03.02.2023 um 07:15 Uhr wurden wir gemeinsam mit der Berufsfeuerwehr Innsbruck per Sirene und Pager zu einem Kellerbrand in einem Mehrfamilienhaus alarmiert. Beim Eintreffen der BF Innsbruck stellte sich heraus, dass es sich nicht um einen Kellerbrand sondern um einen Fahrzeugbrand in der Tiefgarage handelte. Wir rückten umgehend mit Kommando und Tanklöschfahrzeug aus. Der 1. Atemschutztrupp erhielt den Auftrag sofort das Stiegenhaus und das Hauptgebäude (Bürogebäude) auf Personen und Verrauchungen zu kontrollieren. In weiterer Folge wurde dieser ATS-Trupp in die komplett verrauchte Tiefgarage beordert um dort Nachschau zu halten und Nachlöscharbeiten am brennenden Fahrzeug durchzuführen. Ein weiterer Atemschutztrupp unserer Einheit kontrollierte in weiterer Folge noch 2 weitere Stiegenhausaufgänge und der 3. ATS Trupp verblieb als Reservetrupp auf Bereitschaft. Im Laufe des Einsatzes wurden noch CO Messungen in den Stiegenhäusern und Wohnungen durchgeführt, welche alle negativ verliefen. In weiterer Folge wurde der LUF (Luftunterstützungsfahrzeug) der BF in der Tiefgarage eingesetzt und wir belüfteten gemeinsam mit der BF die 3 Stiegenhausaufgänge, so dass diese nicht durch Rauchverschleppungen verraucht werden konnte. Der 3. ATS Trupp wurde dann in ein angrenzendes Gebäude geschickt, da bei einer durchgeführten Kontrolle festgestellt wurde, dass dort das Stiegenhaus in Richtung Keller und Tiefgarage noch starke Verrauchungen aufwies. Das Stiegenhaus wurde belüftet und bis zum Eintreffen der Feuer- und Baupolizei gesperrt. Gegen 10:45 Uhr konnte unsere Einsatzmannschaft abrücken. Das TLFH und KLF wurden einsatzbereit gemacht und die Reinigungsarbeiten werden dann am Abend fortgeführt. Ein Dank noch an die Fa. M-Preis welche uns mit Kaffee und etwas Süßen verköstigte. \r\n\nAm Einsatzort: BF Innsbruck, FF Reichenau, Rotes Kreuz Innsbruck, Polizei, Stadtmagsitrat Innsbruck; \r\n\nHelmut PLANK, Kommandant','2023-02-03','FF Reichenau',1,'2026-04-09 11:31:48','2026-04-09 11:31:48'),(12,'THL - Innuferreinigung','einsatz','Am 13.04.2024 nahm, wie jedes Jahr, auch die Freiwillige Feuerwehr Reichenau an der groß angelegten Innuferreinigung teil. 12 Kameraden/innen reinigten dabei den südlichen Innuferbereich von der Tiflisbrücke bis zur Grenoblerbrücke. Laut den Kameraden/Innen wurde zwar wieder einiges an Müll gesammelt aber nicht so viel wie die letzten Jahre. Unter anderem konnte sogar ein weggeworfener, jedoch bereits sehr röstiger und verwitterter Rollstuh aufgefunden werden. Danke an die Kameraden/Innen, welche sich die Zeit für diese sehr wichtige Arbeit genommen haben. \r\n\nHelmut PLANK, Kommandant','2024-04-13','FF Reichenau',1,'2026-04-09 11:31:48','2026-04-09 11:31:48'),(13,'Zimmerbrand','einsatz','Am 31.03.2024 um 23:19 Uhr wurden wir zur Unterstützung der Berufsfeuerwehr Innsbruck zu einem Wohnungsbrand mittels Sirene und Pager alarmiert. Nach unserem Eintreffen erhielten wir den Auftrag das total verrauchte Stiegenhaus zu kontrollieren und die Anwohner zu beruhigen. Ein weiterer Atemschutztrupp verblieb als Rettungstrupp vor dem Hauseingang. Der Brand konnte von der BF rasch unter Kontrolle gebracht, das Stiegenhaus und Wohnung belüftet werden. Im Anschluss an die Löscharbeiten konnte der Bezirksbrandermittler der Polizei die Arbeit aufnehmen. Neben der Berufsfeuerwehr und uns, waren noch das Rote Kreuz und die Polizei vor Ort. Die FF Amras besetzte derweilen ihre Wache als Bereitschaftseinheit. Nach ca. 1 Stunde konnte der Einsatz von uns beendet werden. Die FF Reichenau stand mit 4 Fahrzeugen und 24 Männer und Frauen im Einsatz. \r\n\nHelmut PLANK, Kommandant','2024-03-31','FF Reichenau',1,'2026-04-09 11:31:48','2026-04-09 11:31:48'),(14,'Brandsicherheitswache-Tuifltreffen','einsatz','Zum 10 Jahresjubiläum der \"Innsbrucker Alpentuifl\" veranstaltete der Verein ein \"Tuifltreffen\" in der Reichenau. Wir übernahmen natürlich wieder die Brandsicherheitswache bei diesem Event. Während der Auftritte der verschiedenen \"Tuiflgruppen\" kam es zu keinen nenneswerten Vorfällen und so konnten die Kameraden/Innen nach der BSW gegen 22:00 Uhr wieder einrücken. Wir waren mit 10 Mann/Frau und 2 Fahrzeugen vor Ort. Wir gratulieren den \"Innsbrucker Alpentuifl\" unter ihrem Obmann Marcel R. zu dieser großartigen Veranstaltung und zu ihrem 10 jährigen Jubiläum. \r\n\nHelmut PLANK, Kommandant','2024-11-30','FF Reichenau',1,'2026-04-09 11:31:48','2026-04-09 11:31:48'),(15,'Unterstützungseinsatz Kematen i. Tirol','einsatz','Am 12.08.2024 kurz vor Mitternacht wurden wir von der Leitstelle Tirol zu einem Unterstützungseinsatz mit unserer Großpumpe nach Kematen in Tirol alarmiert. Wir rückten mit den Fahrzeugen LAST1, dem TLFH und dem Großpumpenanhänger in Richtung Kematen aus. Vor Ort galt es dann gemeinsam mit den Kameraden der FF Lans und deren Großpumpe eine Straßenunterführung auszupumpen. Ablösen konnten wir dadurch die an der Einsatzstelle anwesenden Kameraden der FF Zirl und FF Kematen mit ihren Schmutzwasserpumpen. Kurz vor 02:30 Uhr konnten wir nach einer Grobreinigung der Ausrüstung wieder in Richtung Wache einrücken, wo die Einsatzbereitschaft wieder hergestellt wurde. Die letzten Kameraden verließen gegen 03:30 Uhr die Wache und mussten nach einer kurzen Nacht, in der Früh wieder zur Arbeit. \r\n\nHelmut PLANK, Kommandant','2024-08-12','FF Reichenau',1,'2026-04-09 11:31:48','2026-04-09 11:31:48');
